export const meta = {
  "slug": "heroicons-lock-open",
  "family": "heroicons",
  "name": "lock-open",
  "category": "Status",
  "motion": "lock",
  "component": "createHeroiconsLockOpenIcon"
};

export function createHeroiconsLockOpenIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
